import type {
  HeaderActionsProps,
  HeaderBreadcrumbsProps,
  HeaderContentProps,
  HeaderProps,
  HeaderTitleProps,
} from "./header.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { HeaderClasses, StyledHeader } from "./header.styles";

const HeaderRoot = forwardRef(
  (
    { className, variant = "default", children, ...props }: HeaderProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(HeaderClasses.root, className);

    const breadcrumbs = React.Children.map(children, (child) =>
      React.isValidElement(child) && child.type === Breadcrumbs ? child : null,
    );
    const content = React.Children.map(children, (child) =>
      React.isValidElement(child) && child.type === Content ? child : null,
    );
    const actions = React.Children.map(children, (child) =>
      React.isValidElement(child) && child.type === Actions ? child : null,
    );

    return (
      <StyledHeader
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {breadcrumbs}
        <div className={HeaderClasses.main}>
          {content}
          {actions}
        </div>
      </StyledHeader>
    );
  },
);
HeaderRoot.displayName = "Header";

//Title component
const Title: React.FC<HeaderTitleProps> = ({ className, children, headingLevel = 1, ...props }) => {
  const HeadingTag = `h${headingLevel}` as keyof JSX.IntrinsicElements;
  return React.createElement(
    HeadingTag,
    { className: clsx(HeaderClasses.title, className), tabIndex: -1, ...props },
    children,
  );
};
Title.displayName = "Header.Title";

//Subtitle component
const Subtitle: React.FC<HeaderTitleProps> = ({
  className,
  children,
  headingLevel = 2,
  ...props
}) => {
  const HeadingTag = `h${headingLevel}` as keyof JSX.IntrinsicElements;
  return React.createElement(
    HeadingTag,
    { className: clsx(HeaderClasses.subtitle, className), tabIndex: -1, ...props },
    children,
  );
};
Subtitle.displayName = "Header.Subtitle";

// Description component
const Description: React.FC<HeaderTitleProps> = ({ className, children, ...props }) => {
  return React.createElement(
    "div",
    { className: clsx(HeaderClasses.description, className), tabIndex: -1, ...props },
    children,
  );
};
Description.displayName = "Header.Description";

//Content component
const Content: React.FC<HeaderContentProps> = ({ className, children }) => (
  <div className={clsx(HeaderClasses.content, className)}>{children}</div>
);
Content.displayName = "Header.Content";

//Actions component
const Actions: React.FC<HeaderActionsProps> = ({ className, children }) => (
  <div className={clsx(HeaderClasses.actions, className)}>{children}</div>
);
Actions.displayName = "Header.Actions";

//Breadcrumbs component
const Breadcrumbs: React.FC<HeaderBreadcrumbsProps> = ({ className, children }) => (
  <div className={clsx(HeaderClasses.breadcrumbs, className)}>{children}</div>
);
Breadcrumbs.displayName = "Header.Breadcrumbs";

const Header = Object.assign(HeaderRoot, {
  Title,
  Subtitle,
  Description,
  Content,
  Actions,
  Breadcrumbs,
});

export default Header;
